// Server-only: SQLite persistence for users and sessions.
// This module must never be imported from client code.
import { DatabaseSync } from 'node:sqlite'
import { mkdirSync } from 'node:fs'
import { dirname } from 'node:path'

const DB_PATH = '/home/user/tanstack-auth/data/app.db'

mkdirSync(dirname(DB_PATH), { recursive: true })

let dbInstance: DatabaseSync | null = null

function getDb(): DatabaseSync {
  if (dbInstance) return dbInstance

  const db = new DatabaseSync(DB_PATH)
  db.exec('PRAGMA journal_mode = WAL;')
  db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT NOT NULL UNIQUE,
      password_hash TEXT NOT NULL,
      created_at INTEGER NOT NULL
    );
  `)
  db.exec(`
    CREATE TABLE IF NOT EXISTS sessions (
      id TEXT PRIMARY KEY,
      user_id INTEGER NOT NULL,
      created_at INTEGER NOT NULL,
      expires_at INTEGER NOT NULL,
      FOREIGN KEY (user_id) REFERENCES users(id)
    );
  `)

  dbInstance = db
  return db
}

export interface UserRow {
  id: number
  username: string
  password_hash: string
  created_at: number
}

export interface SessionRow {
  id: string
  user_id: number
  created_at: number
  expires_at: number
}

export function createUser(username: string, passwordHash: string): UserRow {
  const db = getDb()
  const stmt = db.prepare(
    'INSERT INTO users (username, password_hash, created_at) VALUES (?, ?, ?)',
  )
  const info = stmt.run(username, passwordHash, Date.now())
  return findUserById(Number(info.lastInsertRowid))!
}

export function findUserByUsername(username: string): UserRow | undefined {
  const db = getDb()
  const stmt = db.prepare('SELECT * FROM users WHERE username = ?')
  return stmt.get(username) as UserRow | undefined
}

export function findUserById(id: number): UserRow | undefined {
  const db = getDb()
  const stmt = db.prepare('SELECT * FROM users WHERE id = ?')
  return stmt.get(id) as UserRow | undefined
}

export function createSession(
  sessionId: string,
  userId: number,
  expiresAt: number,
): void {
  const db = getDb()
  const stmt = db.prepare(
    'INSERT INTO sessions (id, user_id, created_at, expires_at) VALUES (?, ?, ?, ?)',
  )
  stmt.run(sessionId, userId, Date.now(), expiresAt)
}

export function findSession(sessionId: string): SessionRow | undefined {
  const db = getDb()
  const stmt = db.prepare('SELECT * FROM sessions WHERE id = ?')
  return stmt.get(sessionId) as SessionRow | undefined
}

export function deleteSession(sessionId: string): void {
  const db = getDb()
  const stmt = db.prepare('DELETE FROM sessions WHERE id = ?')
  stmt.run(sessionId)
}

// Server-only: password hashing helpers built on Node's built-in scrypt.
// Never store or log plaintext passwords.
import { randomBytes, scrypt as scryptCallback, timingSafeEqual } from 'node:crypto'
import { promisify } from 'node:util'

const scrypt = promisify(scryptCallback)

const KEY_LENGTH = 64

export async function hashPassword(password: string): Promise<string> {
  const salt = randomBytes(16).toString('hex')
  const derivedKey = (await scrypt(password, salt, KEY_LENGTH)) as Buffer
  return `${salt}:${derivedKey.toString('hex')}`
}

export async function verifyPassword(
  storedHash: string,
  password: string,
): Promise<boolean> {
  const [salt, key] = storedHash.split(':')
  if (!salt || !key) return false
  const keyBuffer = Buffer.from(key, 'hex')
  const derivedKey = (await scrypt(password, salt, KEY_LENGTH)) as Buffer
  if (keyBuffer.length !== derivedKey.length) return false
  return timingSafeEqual(keyBuffer, derivedKey)
}

// Server-only: session issuance/lookup/destruction backed by SQLite.
import { randomBytes } from 'node:crypto'
import { deleteCookie, getCookie, setCookie } from '@tanstack/react-start/server'
import {
  createSession as dbCreateSession,
  deleteSession as dbDeleteSession,
  findSession,
  findUserById,
  type UserRow,
} from './db'

const SESSION_COOKIE = 'session_id'
const SESSION_TTL_MS = 1000 * 60 * 60 * 24 * 7 // 7 days

export function issueSession(userId: number): string {
  const sessionId = randomBytes(32).toString('hex')
  dbCreateSession(sessionId, userId, Date.now() + SESSION_TTL_MS)

  setCookie(SESSION_COOKIE, sessionId, {
    httpOnly: true,
    // The app is served over plain HTTP in this environment, so the
    // `secure` flag must be disabled or the browser would drop the cookie.
    secure: false,
    sameSite: 'lax',
    path: '/',
    maxAge: SESSION_TTL_MS / 1000,
  })

  return sessionId
}

export function destroyCurrentSession(): void {
  const sessionId = getCookie(SESSION_COOKIE)
  if (sessionId) {
    dbDeleteSession(sessionId)
  }
  deleteCookie(SESSION_COOKIE, { path: '/' })
}

export function getCurrentSessionUser(): UserRow | null {
  const sessionId = getCookie(SESSION_COOKIE)
  if (!sessionId) return null

  const session = findSession(sessionId)
  if (!session) return null

  if (session.expires_at < Date.now()) {
    dbDeleteSession(sessionId)
    deleteCookie(SESSION_COOKIE, { path: '/' })
    return null
  }

  const user = findUserById(session.user_id)
  return user ?? null
}

// Server functions exposed to the client. These are safe to import from
// route/component files -- the build replaces the implementation with an
// RPC stub on the client bundle, while the real logic (DB + cookies) only
// ever executes on the server.
import { createServerFn } from '@tanstack/react-start'
import { createUser, findUserByUsername } from './db'
import { hashPassword, verifyPassword } from './password'
import {
  destroyCurrentSession,
  getCurrentSessionUser,
  issueSession,
} from './session'

interface Credentials {
  username: string
  password: string
}

function parseCredentials(data: unknown): Credentials {
  const record = (data ?? {}) as Record<string, unknown>
  const username =
    typeof record.username === 'string' ? record.username.trim() : ''
  const password = typeof record.password === 'string' ? record.password : ''

  if (username.length < 3) {
    throw new Error('Username must be at least 3 characters long')
  }
  if (password.length < 6) {
    throw new Error('Password must be at least 6 characters long')
  }

  return { username, password }
}

export const registerUser = createServerFn({ method: 'POST' })
  .validator(parseCredentials)
  .handler(async ({ data }) => {
    const existing = findUserByUsername(data.username)
    if (existing) {
      throw new Error('Username is already taken')
    }

    const passwordHash = await hashPassword(data.password)
    const user = createUser(data.username, passwordHash)
    issueSession(user.id)

    return { username: user.username }
  })

export const loginUser = createServerFn({ method: 'POST' })
  .validator(parseCredentials)
  .handler(async ({ data }) => {
    const user = findUserByUsername(data.username)
    const ok = user
      ? await verifyPassword(user.password_hash, data.password)
      : false

    if (!user || !ok) {
      throw new Error('Invalid username or password')
    }

    issueSession(user.id)

    return { username: user.username }
  })

export const logoutUser = createServerFn({ method: 'POST' }).handler(
  async () => {
    destroyCurrentSession()
    return { success: true }
  },
)

export const getCurrentUser = createServerFn({ method: 'GET' }).handler(
  async () => {
    const user = getCurrentSessionUser()
    if (!user) return null
    return { username: user.username }
  },
)

import { useState } from 'react'
import { Link, createFileRoute, redirect } from '@tanstack/react-router'
import { useServerFn } from '@tanstack/react-start'
import { getCurrentUser, registerUser } from '#/server/auth.functions'

export const Route = createFileRoute('/register')({
  beforeLoad: async () => {
    const user = await getCurrentUser()
    if (user) {
      throw redirect({ to: '/dashboard' })
    }
  },
  component: RegisterPage,
})

function RegisterPage() {
  const navigate = Route.useNavigate()
  const registerFn = useServerFn(registerUser)

  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    setError(null)
    setSubmitting(true)
    try {
      await registerFn({ data: { username, password } })
      await navigate({ to: '/dashboard' })
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Registration failed')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <div className="mx-auto mt-16 max-w-sm p-6">
      <h1 className="text-2xl font-bold">Create an account</h1>
      <form onSubmit={handleSubmit} className="mt-6 flex flex-col gap-4">
        <label className="flex flex-col gap-1">
          <span>Username</span>
          <input
            name="username"
            type="text"
            autoComplete="username"
            required
            minLength={3}
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            className="rounded border border-gray-300 px-3 py-2"
          />
        </label>
        <label className="flex flex-col gap-1">
          <span>Password</span>
          <input
            name="password"
            type="password"
            autoComplete="new-password"
            required
            minLength={6}
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="rounded border border-gray-300 px-3 py-2"
          />
        </label>
        {error && <p className="text-sm text-red-600">{error}</p>}
        <button
          type="submit"
          disabled={submitting}
          className="rounded bg-blue-600 px-4 py-2 font-semibold text-white disabled:opacity-50"
        >
          {submitting ? 'Creating account…' : 'Register'}
        </button>
      </form>
      <p className="mt-4 text-sm">
        Already have an account?{' '}
        <Link to="/login" className="text-blue-600 underline">
          Log in
        </Link>
      </p>
    </div>
  )
}

